import { chromium } from 'playwright';
const b = await chromium.launch({ headless: true });
const p = await b.newPage();
await p.goto('http://127.0.0.1:60694');
await p.fill('#email','ops@lab.test');
await p.fill('#password','lab-ops-pass');
await p.click('button[type=submit]');
await p.waitForLoadState('networkidle');
await p.goto('http://127.0.0.1:60694/pipeline');
await p.waitForLoadState('networkidle');
const names = () => p.$$eval('#pl .nm', n => n.map(x => x.textContent));
async function drag(from, to) { // indexes
  const handles = await p.$$('#pl .h');
  const hb = await handles[from].boundingBox();
  const lis = await p.$$('#pl li');
  const tb = await lis[to].boundingBox();
  await p.mouse.move(hb.x + hb.width/2, hb.y + hb.height/2);
  await p.mouse.down();
  const ty = to < from ? tb.y + 2 : tb.y + tb.height - 2;
  await p.mouse.move(hb.x + hb.width/2, ty, { steps: 15 });
  await p.mouse.up();
}
console.log('start', await names());
await drag(4, 0); // Picking to top
console.log('after1', await names());
await drag(1, 2); // Packing (now idx1) down past Intake
console.log('after2', await names());
